// Observe INP candidates
const observer = new PerformanceObserver((list) => {
  for (const entry of list.getEntries()) {
    // entry.duration includes input delay + processing + presentation
    console.log('Interaction:', entry.name, entry.duration);

    if (entry.duration > 200) {
      console.warn('Slow interaction detected');
    }
  }
});
observer.observe({ type: 'event', buffered: true });

// Common INP fixes:
// 1. Break up long tasks
async function handleClick(e) {
  e.preventDefault();
  await doFirstThing();
  await yieldToMain();
  await doSecondThing();
}

async function yieldToMain() {
  await new Promise(r => setTimeout(r, 0));
}

// 2. Reduce input delay by removing long event listeners
// 3. Use passive event listeners for scroll/touch
button.addEventListener('touchstart', handler, { passive: true });

import { onLCP, onINP, onCLS, onFCP, onTTFB } from 'web-vitals';

function send(metric) {
  const body = JSON.stringify({
    name: metric.name,
    value: metric.value,
    rating: metric.rating,
    id: metric.id
  });

  // Use sendBeacon for reliability on unload
  if (navigator.sendBeacon) {
    navigator.sendBeacon('/api/vitals', body);
  } else {
    fetch('/api/vitals', { method: 'POST', body, keepalive: true });
  }
}

// Observe all Core Web Vitals
onLCP(send);
onINP(send);
onCLS(send);
onFCP(send);
onTTFB(send);

// Optional: debug attribution
import { onLCP as onLCPWithAttribution } from 'web-vitals/attribution';
onLCPWithAttribution((metric) => {
  console.log('LCP element:', metric.attribution.element);
  console.log('LCP URL:', metric.attribution.url);
});
